insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-011:policy:supervision:2')::uuid, 'PE-011', 'https://themightyjungle.ca/Home/Rules', '2026-11-07', 'verified', null, 'supervision', 'Mighty Jungle is an unsupervised play area: parents and guardians are fully responsible for their children''s safety.', 2);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-011:policy:waiver:3')::uuid, 'PE-011', 'https://themightyjungle.ca/Home/Rules', '2026-11-07', 'verified', null, 'waiver', 'A waiver must be signed for each child in the facility.', 3);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-011:policy:dress_socks:4')::uuid, 'PE-011', 'https://themightyjungle.ca/Home/Rules', '2026-11-07', 'verified', null, 'dress_socks', 'Socks are mandatory for parents and children in the play area: no shoes or bare feet. Shoes are fine in the lounge. Socks are sold at the front desk.', 4);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-011:policy:booking_rule:5')::uuid, 'PE-011', 'https://themightyjungle.ca/Home/Faq', '2026-11-07', 'verified', null, 'booking_rule', 'Drop-in is weekdays only. Weekends are open for private birthday parties only, with no walk-ins.', 5);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-011:policy:hours_note:6')::uuid, 'PE-011', 'https://themightyjungle.ca/Home/Prices', '2026-11-07', 'verified', null, 'hours_note', 'Saturday and Sunday: private parties only.', 6);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-011:policy:hours_note:7')::uuid, 'PE-011', 'https://themightyjungle.ca/Home/Prices', '2026-11-07', 'verified', null, 'hours_note', 'Drop-in and play hours may vary during the winter months, and some evenings might be closed for private parties, so call before heading out.', 7);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-011:policy:food_rule:8')::uuid, 'PE-011', 'https://themightyjungle.ca/Home/Rules', '2026-11-07', 'verified', null, 'food_rule', 'Peanut/nut-free facility: no peanut or nut products. No eating, drinking or gum chewing in the play area.', 8);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-011:policy:food_rule:9')::uuid, 'PE-011', 'https://themightyjungle.ca/Home/Faq', '2026-11-07', 'verified', 'The FAQ gives this answer among its party questions; it doesn''t say whether it applies to drop-in visits.', 'food_rule', 'Outside food and drinks are allowed as long as everything is nut/peanut-free.', 9);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-011:policy:restriction:10')::uuid, 'PE-011', 'https://themightyjungle.ca/Home/Rules', '2026-11-07', 'verified', null, 'restriction', 'No toys on the climbing structure, no climbing on the outside of the structure, no running, and no sharp objects. Rough play means removal from the play area.', 10);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-011:policy:other:11')::uuid, 'PE-011', 'https://themightyjungle.ca/Home/Rules', '2026-11-07', 'verified', null, 'other', 'Please use hand sanitizer before entering the play area, and visit another day if you or your child aren''t feeling well.', 11);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-011:policy:other:12')::uuid, 'PE-011', 'https://themightyjungle.ca/Home/Prices', '2026-11-07', 'verified', null, 'other', 'Prices are subject to change without notice.', 12);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-011:policy:party:13')::uuid, 'PE-011', 'https://themightyjungle.ca/Home/Parties', '2026-11-07', 'verified', null, 'party', 'Parties are fully private and last 2 hours. The venue books 3–4 months ahead; reserve by phone or in person, with a $100 non-refundable deposit.', 13);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-011:policy:party:14')::uuid, 'PE-011', 'https://themightyjungle.ca/Home/Rules', '2026-11-07', 'verified', 'The rules page says an extra half hour is $50; the FAQ says $70.', 'party', 'An extra half hour can be added for $50 when available; a party that runs past its end time is charged $70.', 14);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-011:policy:party:15')::uuid, 'PE-011', 'https://themightyjungle.ca/Home/Rules', '2026-11-07', 'verified', null, 'party', 'Arrive no sooner than 5 minutes before the party. No piñatas or face painting; helium balloons only if weighted; no tape on the walls. Children who aren''t fully potty trained need proper apparel.', 15);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-011:policy:party:16')::uuid, 'PE-011', 'https://themightyjungle.ca/Home/Parties', '2026-11-07', 'verified', null, 'party', 'Wacky Tuesdays: 20% off a party booked for a Tuesday. Crazy Thursdays: a free half hour on any package for a Thursday party.', 16);

